from typing import Any, Dict, Mapping

from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location
from stockflow.parse_quantity import parse_quantity

_VALID_TYPES = {"RCV", "SHP", "RTN", "ADJ"}


def parse_movement_line(line: str, case_sizes: Mapping[str, int]) -> Dict[str, Any]:
    """Parse one stock movement record into a normalized dict.

    Records are semicolon-separated: day;type;sku;location;quantity.
    Returns {day, type, sku, location, qty} where qty is the signed change
    in eaches. RCV/RTN add stock, SHP removes it, ADJ applies as written.
    RCV, SHP, RTN quantities must be strictly positive as written; a zero or
    negative value on those types is a data-entry error (ValueError). A zero
    ADJ is also rejected. Only ADJ may carry a sign.
    """
    fields = [f.strip() for f in line.split(";")]
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}")

    day_raw, type_raw, sku_raw, loc_raw, qty_raw = fields

    try:
        day = int(day_raw)
    except ValueError:
        raise ValueError(f"bad day: {day_raw!r}")
    if day < 0:
        raise ValueError(f"day must be non-negative: {day}")

    mtype = type_raw.upper()
    if mtype not in _VALID_TYPES:
        raise ValueError(f"unknown type: {type_raw!r}")

    sku = normalize_sku(sku_raw)

    zone, aisle, shelf, level = parse_location(loc_raw)
    location = f"{zone}-{aisle:02d}-{shelf:02d}-{level}"

    case_size = case_sizes.get(sku, 1)
    raw_qty = parse_quantity(qty_raw, case_size)

    if mtype in ("RCV", "RTN", "SHP"):
        if raw_qty <= 0:
            raise ValueError(f"{mtype} quantity must be strictly positive: {qty_raw!r}")
        qty = -raw_qty if mtype == "SHP" else raw_qty
    else:
        if raw_qty == 0:
            raise ValueError(f"ADJ quantity must be non-zero: {qty_raw!r}")
        qty = raw_qty

    return {"day": day, "type": mtype, "sku": sku, "location": location, "qty": qty}
